"use strict";
// A promise subclass at module initialization, as provider SDKs ship it
// (`class APIPromise extends Promise {}` in openai's core/api-promise.mjs):
// the class construction needs the JavaScript runtime's promise, so the
// native pipeline fences the module where it evaluates. A build runs the
// package in a Node island for that fence.
class SdkPromise extends Promise {}
module.exports = {
  send: function send(params, input, betas) {
    return JSON.stringify([params, input, betas]);
  },
  assistant: function assistant() {
    return { role: "assistant", content: null };
  },
  SdkPromise: SdkPromise,
};
